//! Differential corpus generated by the pinned original deployment's tree functions.
//! JXPAN_LIVE_ORACLE=1 reruns the exact private original-source oracle.
mod support;
use jxpan_rust::tree;

use serde_json::{Value, json};
use std::cell::{Cell, RefCell};
use std::future::poll_fn;
use std::rc::Rc;
use std::task::Poll;
use tree::{Walk, nested_tree, walk};

#[derive(Default)]
struct Trace {
    calls: RefCell<Vec<String>>,
    active: Cell<usize>,
    peak: Cell<usize>,
}

fn oracle() -> Value {
    support::oracle("tree", include_str!("fixtures/tree.json"))
}

async fn execute(input: &Value) -> (Walk, Rc<Trace>) {
    let graph = input["graph"].clone();
    let failures = input["failures"].as_array().cloned().unwrap_or_default();
    let trace = Rc::new(Trace::default());
    let callback_trace = trace.clone();
    let walked = walk(
        move |id: String| {
            let trace = callback_trace.clone();
            trace.calls.borrow_mut().push(id.clone());
            let mut entries = Some(
                graph
                    .get(&id)
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default(),
            );
            let fails = failures.iter().any(|failure| failure.as_str() == Some(&id));
            let mut remaining = 1 + id.chars().map(|c| c as usize).sum::<usize>() % 4;
            let mut started = false;
            poll_fn(move |cx| {
                if !started {
                    started = true;
                    trace.active.set(trace.active.get() + 1);
                    trace.peak.set(trace.peak.get().max(trace.active.get()));
                }
                if remaining > 0 {
                    remaining -= 1;
                    cx.waker().wake_by_ref();
                    return Poll::Pending;
                }
                trace.active.set(trace.active.get() - 1);
                Poll::Ready(if fails {
                    Err("offline list failure")
                } else {
                    Ok(entries.take().expect("polled after completion"))
                })
            })
        },
        input["rootId"].as_str().unwrap(),
        input["rootName"].as_str().unwrap(),
        input["concurrency"].as_u64().unwrap() as usize,
        input["maxNodes"].as_u64().unwrap() as usize,
    )
    .await;
    assert_eq!(trace.active.get(), 0);
    (walked, trace)
}

fn normalized_walk(walked: &Walk, epoch: &Value) -> Value {
    let mut value = walked.to_json();
    for (_, node) in value["nodes"].as_object_mut().unwrap() {
        assert!(
            node["_preloadedAt"].as_u64().is_some(),
            "real timestamp missing"
        );
        node["_preloadedAt"] = epoch.clone();
    }
    value
}

fn key_orders(value: &Value) -> Value {
    fn visit(value: &Value, path: &mut Vec<String>, out: &mut Vec<Value>) {
        let Some(object) = value.as_object() else {
            return;
        };
        out.push(json!({"path": path, "keys": object.keys().collect::<Vec<_>>()}));
        for (key, child) in object {
            path.push(key.clone());
            visit(child, path, out);
            path.pop();
        }
    }
    let mut out = Vec::new();
    visit(value, &mut Vec::new(), &mut out);
    json!(out)
}

fn assert_walk(
    walked: &Walk,
    trace: &Trace,
    expected: &Value,
    epoch: &Value,
    name: &str,
    order_errors: &mut Vec<String>,
) {
    assert_eq!(
        normalized_walk(walked, epoch),
        expected["walk"],
        "walk: {name}"
    );
    assert_eq!(
        json!(trace.calls.borrow().as_slice()),
        expected["calls"],
        "request queue: {name}"
    );
    assert_eq!(
        json!(trace.peak.get()),
        expected["peak"],
        "bounded batch concurrency: {name}"
    );
    let keys = json!(walked.nodes.keys().collect::<Vec<_>>());
    if keys != expected["nodeKeys"] {
        order_errors.push(format!(
            "JS node key order: {name}: actual={keys}, expected={}",
            expected["nodeKeys"]
        ));
    }
    for file in &walked.all_files {
        let id = file["fileId"].as_str().unwrap();
        assert_eq!(
            walked.file(id),
            walked.all_files.iter().find(|row| row["fileId"] == id)
        );
    }
    assert!(walked.file("not-present-offline").is_none());
}

#[tokio::test]
async fn exact_deployed_functions_match_139_normal_vectors_and_3_cycle_walks() {
    let oracle = oracle();
    assert_eq!(
        oracle["sourceHash"],
        "47e2a84566ffa338a420113818a4bb629d3a43f4290dd65547c52b4cfe23f118"
    );
    assert_eq!(
        oracle["functionHash"],
        "84d7da035abc17d7275a6e6bb410626c698be49ace4241169d67baa869dfbf56"
    );
    let vectors = oracle["vectors"].as_array().unwrap();
    assert_eq!(vectors.len(), 139);
    let mut order_errors = Vec::new();
    for vector in vectors {
        let input = &vector["input"];
        let expected = &vector["expected"];
        let name = input["name"].as_str().unwrap();
        let (walked, trace) = execute(input).await;
        assert_walk(
            &walked,
            &trace,
            expected,
            &oracle["epoch"],
            name,
            &mut order_errors,
        );
        let actual = nested_tree(
            &walked,
            input["startId"].as_str().unwrap_or(""),
            input["startName"].as_str().unwrap_or(""),
        );
        assert_eq!(actual, expected["nested"], "nested: {name}");
        if key_orders(&actual) != expected["keyOrders"] {
            order_errors.push(format!("JS nested key order: {name}"));
        }
    }
    let safety = oracle["safetyVectors"].as_array().unwrap();
    assert_eq!(safety.len(), 3);
    for vector in safety {
        let input = &vector["input"];
        let name = input["name"].as_str().unwrap();
        assert_eq!(vector["originalNestedExecuted"], false);
        let (walked, trace) = execute(input).await;
        assert_walk(
            &walked,
            &trace,
            &vector["expectedWalk"],
            &oracle["epoch"],
            name,
            &mut order_errors,
        );
        let expected_safe = match name {
            "self-cycle" => json!({"root": {"back": {}}}),
            "two-node-cycle" => json!({"root": {"A": {"back": {}}}}),
            "three-node-cycle" => json!({"root": {"A": {"B": {"back": {}}}}}),
            _ => panic!("unrecognized explicit safety case"),
        };
        // Handwritten SAFE expectation, never claimed as original nested parity.
        assert_eq!(
            nested_tree(&walked, "", ""),
            expected_safe,
            "cycle safety: {name}"
        );
    }
    // Finish all value/request/safety comparisons before reporting feature-sensitive
    // enumeration errors; this does not skip any order assertion.
    assert!(
        order_errors.is_empty(),
        "{} ordering mismatches (enable serde_json preserve_order); first: {:?}",
        order_errors.len(),
        order_errors.first()
    );
}

#[test]
fn deep_graph_is_iterative_and_caps_serializable_depth() {
    let mut walked = Walk {
        root_id: "0".into(),
        nodes: serde_json::Map::new(),
        all_files: vec![],
        all_folders: vec![],
        visited: 5000,
    };
    for i in 0..5000 {
        walked.nodes.insert(
            i.to_string(),
            json!({"folders": [{"fileId": (i + 1).to_string(), "fileName": "next"}], "files": []}),
        );
    }
    let nested = nested_tree(&walked, "", "");
    let mut cursor = &nested["root"];
    let mut depth = 0;
    while let Some(next) = cursor.get("next") {
        depth += 1;
        cursor = next;
    }
    assert_eq!(depth, tree::MAX_NESTED_DEPTH);
    assert_eq!(cursor, &json!({}));
    assert!(serde_json::to_string(&nested).is_ok());
}

#[tokio::test]
async fn prototype_key_is_literal_safe_data_not_mutation() {
    let walked = walk(
        |id: String| async move {
            Ok::<_, ()>(if id == "r" {
                vec![json!({"fileId": "__proto__", "fileName": "__proto__", "isFolder": true})]
            } else {
                vec![json!({"fileId": "f", "fileName": "__proto__", "fileSize": 5})]
            })
        },
        "r",
        "Share",
        0,
        0,
    )
    .await;
    assert_eq!(walked.visited, 2);
    assert!(walked.nodes.contains_key("__proto__"));
    // Intentional hardening, not a differential parity assertion.
    assert_eq!(
        nested_tree(&walked, "", ""),
        json!({"root": {"__proto__": {"__proto__": {"id": "f", "size": 5}}}})
    );
}
